# Reference values from OrdinaryDiffEqMultirate (MREEF, MRAB, MRIGARKERK22a,
# MRIGARKERK22b, MRIGARKERK33a, MRIGARKERK45a, MIS) and
# OrdinaryDiffEqMultirateImplicit 1.0.1 (MREIL, MRIGARKIRK21a,
# MRIGARKESDIRK34a, MRIGARKESDIRK46a), generated by tools/multirate-probe.jl:
# points, nf, nf2, njacs, nw, nsolve, naccept, nreject and the final state
# of split problems with a fast part f1 and a slow part f2 (g1 and the stiff
# slow g2 for the implicit MRI-GARK methods): adaptive solves (the longer
# ones at loose tolerances), fixed steps of 1/16, an event halving the state
# at t = 1/2, the analytic Jacobian of f1 and a diagonal mass matrix for
# MREIL. The solves of the probe that take thousands of steps at tight
# tolerances also match; they are left out here for time.

mr_f1 <- function(u, p, t) c(-p[1] * u[1] + u[2] * u[2] + 0.5 * t, -p[1] * (u[2] - u[1]) - 0.5 * t * u[2])
mr_f2 <- function(u, p, t) c(u[2] - 0.1 * u[1] * u[1] * u[1] + t, -u[1] + 0.2 * u[2] * t)
mr_g1 <- function(u, p, t) c(-2 * u[1] + u[2] + 0.25 * t, u[1] - 3 * u[2])
mr_g2 <- function(u, p, t) c(-p[1] * (u[1] - u[2] * u[2]) + t, -p[1] * u[2] + 0.5 * u[1] * u[1])
mr_j1 <- function(u, p, t) rbind(c(-p[1], 2 * u[2]), c(p[1], -p[1] - 0.5 * t))
mr_cb <- DiscreteCallback(function(u, t, integ) t == 0.5, function(integ) integ$u <- integ$u * 0.5)

mr_alg <- function(name) {
  fd <- AutoFiniteDiff()
  switch(name,
    MREEF = MREEF(), MREEF_r3 = MREEF(m = 3, order = 3, seq = "romberg"), MREEF_o2 = MREEF(m = 6, order = 2),
    MRAB = MRAB(), MRAB_k1 = MRAB(k = 1, m = 5), MRAB_k3 = MRAB(k = 3, m = 6), MRAB_k4 = MRAB(k = 4, m = 8),
    MRAB_k5 = MRAB(k = 5, m = 8), MRIGARKERK22a = MRIGARKERK22a(m = 4), MRIGARKERK22b = MRIGARKERK22b(m = 4),
    MRIGARKERK33a = MRIGARKERK33a(m = 3), MRIGARKERK45a = MRIGARKERK45a(m = 2), MIS = MIS(m = 6),
    MREIL = MREIL(autodiff = fd), MREIL_r3 = MREIL(m = 2, order = 3, seq = "romberg", autodiff = fd),
    MRIGARKIRK21a = MRIGARKIRK21a(m = 3, autodiff = fd), MRIGARKESDIRK34a = MRIGARKESDIRK34a(m = 2, autodiff = fd),
    MRIGARKESDIRK46a = MRIGARKESDIRK46a(m = 2, autodiff = fd))
}

mr_solve <- function(name, case) {
  pv <- as.numeric(sub(".*_", "", case))
  kind <- sub("_.*", "", case)
  stiff <- grepl("^MRIGARK(IRK|ESDIRK)", name)
  prob <- if (kind %in% c("jacfixed", "jacadaptive")) {
    SplitODEProblem(SplitFunction(mr_f1, mr_f2, jac = mr_j1), c(1, 0.5), c(0, 1), pv)
  } else if (kind %in% c("massfixed", "massadaptive")) {
    SplitODEProblem(mr_f1, mr_f2, c(1, 0.5), c(0, 1), pv, mass_matrix = diag(c(1, 2)))
  } else {
    SplitODEProblem(if (stiff) mr_g1 else mr_f1, if (stiff) mr_g2 else mr_f2, c(1, 0.5), c(0, 1), pv)
  }
  opts <- if (grepl("adaptive", kind)) list(reltol = 1e-6, abstol = 1e-8) else if (kind == "loose")
    list(reltol = 1e-3, abstol = 1e-5) else list(dt = 1 / 16, adaptive = FALSE)
  if (startsWith(kind, "cb")) opts <- c(opts, list(callback = mr_cb, tstops = 0.5))
  if (name == "MRAB_k1") opts$maxiters <- 50
  suppressWarnings(do.call(solve, c(list(prob, mr_alg(name)), opts)))
}

