test_that("the multirate methods follow OrdinaryDiffEqMultirate and OrdinaryDiffEqMultirateImplicit", {
  for (r in mr_cases) {
    sol <- mr_solve(r$alg, r$case)
    st <- sol$stats
    lab <- paste(r$alg, r$case)
    expect_equal(c(length(sol$t), st$nf, st$nf2, st$njacs, st$nw, st$nsolve, st$naccept, st$nreject), r$stats,
                 label = lab)
    expect_equal(sol$u[[length(sol$u)]], r$u, tolerance = 1e-12, label = lab)
    rc <- if (r$alg == "MRAB_k1" && grepl("adaptive", r$case)) "MaxIters" else
      if (r$stats[1L] == 1L) "ConvergenceFailure" else "Success"
    expect_equal(sol$retcode, rc, label = lab)
  }
})

test_that("a multirate solve stops before accepting a state that is not finite", {
  # MRAB(k = 5, m = 8) with dt = 1/16 blows up in the seventh step; Julia
  # saves that step (NaN) and then stops, R stops before saving it
  prob <- SplitODEProblem(mr_f1, mr_f2, c(1, 0.5), c(0, 1), 60)
  expect_warning(sol <- solve(prob, MRAB(k = 5, m = 8), dt = 1 / 16, adaptive = FALSE), "non finite")
  expect_equal(sol$retcode, "Unstable")
  expect_equal(length(sol$t), 6L)
  expect_equal(sol$stats$naccept, 5L)
})

test_that("the multirate methods check their options and the problem", {
  expect_error(MRAB(k = 6), "MRAB: `k` must satisfy 1 <= k <= 5")
  expect_error(MRAB(m = 0), "MRAB: `m` must be >= 1")
  expect_error(MIS(m = 0), "MIS: `m` must be >= 1")
  expect_error(MRIGARKERK33a(m = 0), "MRIGARKERK33a: `m` must be >= 1")
  expect_error(MREIL(order = 1), "MREIL: `order` must be >= 2")
  expect_error(MREEF(seq = "fibonacci"), "unknown sequence")
  prob <- SplitODEProblem(mr_f1, mr_f2, c(1, 0.5), c(0, 1), 20)
  expect_error(solve(prob, MREEF(order = 1), reltol = 1e-6), "needs `order` >= 2")
  expect_equal(solve(prob, MREEF(order = 1), dt = 1 / 16, adaptive = FALSE)$retcode, "Success")
  expect_error(solve(ODEProblem(function(u, p, t) -u, 1, c(0, 1)), MIS(m = 6), dt = 0.1), "SplitODEProblem")
  expect_error(MIS(), "missing")
})
